import numpy

class DataHolder:
    def __init__(self):
        self.df = polars.DataFrame({
            "value": [1, 2, 3, 4],
            "score": [0.1, 0.3, 0.5, 0.9]
        })

    def normalize(self):
        arr = numpy.array(self.df["score"])
        return (arr - arr.min()) / (arr.max() - arr.min())

def show_table():
    dh = DataHolder()
    print("Normalized:", dh.normalize())
